# SECTION 14 // AGENT 1.2: COMPOSITE KEY & FOREIGN KEY DISCOVERY AGENT
# STAGE      : Stage 1 - Privacy & Topology
# SOURCE FILE: autonomous_engine/composite_key_detector.py
# DESCRIPTION: Identifies composite candidate keys and foreign key links across raw tables.
####################################################################################################

"""
=============================================================================
ENTERPRISE COMPOSITE KEY & MULTI-COLUMN RELATIONSHIP DETECTOR
=============================================================================
Defeats Weakness #1: Composite Foreign Keys Blindspot.
Solves:
- Relationships spanning 2 or 3 columns (e.g. store_id + region, flight + date)
- Accidental row duplication caused by joining on only 1 column of a composite key
Algorithm:
1. Detects minimal composite candidate keys where tuple uniqueness == 1.0.
2. Cross-evaluates multi-column pairs across tables to recommend composite joins.
=============================================================================
"""

import sys
from itertools import combinations
from typing import Dict, List, Tuple, Any
import pandas as pd

if sys.platform == "win32":
    sys.stdout.reconfigure(encoding='utf-8')

def find_candidate_composite_keys(
    df: pd.DataFrame,
    candidate_cols: List[str] = None,
    max_k: int = 3
) -> List[Tuple[str, ...]]:
    """
    Finds combinations of 2 or 3 columns that form a strictly unique composite key.
    """
    if candidate_cols is None:
        # Filter to ID, code, category, and date columns
        candidate_cols = [
            c for c in df.columns 
            if any(k in str(c).lower() for k in ['id', 'code', 'num', 'key', 'date', 'year', 'month', 'region', 'store', 'type'])
        ]
        
    n_rows = len(df)
    if n_rows == 0 or len(candidate_cols) < 2:
        return []
        
    valid_composites = []
    # Test combinations of length 2 and 3
    for k in range(2, min(max_k + 1, len(candidate_cols) + 1)):
        for combo in combinations(candidate_cols, k):
            # Check composite uniqueness
            uniques = df.duplicated(subset=list(combo)).sum()
            if uniques == 0:
                valid_composites.append(combo)
                
    return valid_composites

def detect_composite_join_mapping(
    df_left: pd.DataFrame, left_name: str,
    df_right: pd.DataFrame, right_name: str
) -> List[Dict[str, Any]]:
    """
    Detects if Left and Right tables share composite keys that must be joined together.
    """
    shared_cols = [c for c in df_left.columns if c in df_right.columns]
    if len(shared_cols) < 2:
        return []
        
    results = []
    for k in range(2, min(4, len(shared_cols) + 1)):
        for combo in combinations(shared_cols, k):
            combo_list = list(combo)
            dups_left = int(df_left.duplicated(subset=combo_list).sum())
            dups_right = int(df_right.duplicated(subset=combo_list).sum())
            
            # If at least one side is unique on the composite key, it is a valid composite relation!
            if dups_left == 0 or dups_right == 0:
                results.append({
                    "left_table": left_name,
                    "right_table": right_name,
                    "composite_keys": combo_list,
                    "is_left_unique": (dups_left == 0),
                    "is_right_unique": (dups_right == 0),
                    "join_type": "Composite 1:N Join" if (dups_right == 0 and dups_left > 0) else "Composite 1:1 Join",
                    "recommendation": f"Must join ON {' AND '.join([f'{left_name}.{c} = {right_name}.{c}' for c in combo_list])} to prevent Cartesian row explosion."
                })
                
    return results

if False and __name__ == "__main__":  # Section CLI preserved for reference
    # Test with retail store + region composite key scenario
    sales = pd.DataFrame({
        "store_id": [101, 101, 102, 102],
        "region_code": ["EAST", "WEST", "EAST", "WEST"],
        "sales_amount": [5000, 7000, 4500, 8000]
    })
    store_meta = pd.DataFrame({
        "store_id": [101, 101, 102, 102],
        "region_code": ["EAST", "WEST", "EAST", "WEST"],
        "manager_name": ["Alice", "Bob", "Charlie", "David"]
    })
    
    print("[*] Testing Composite Key Detector...")
    matches = detect_composite_join_mapping(sales, "Sales_Fact", store_meta, "Store_Dim")
    import json
    print(json.dumps(matches, indent=2))


####################################################################################################
# SECTION 15 // AGENT 1.3: CARDINALITY HAZARD & MULTIPLICITY DEFENSE SCANNER
# STAGE      : Stage 1 - Privacy & Topology
# SOURCE FILE: autonomous_engine/cardinality_and_bridge_detector.py
# DESCRIPTION: Scans for 1:1, 1:N, and N:M cardinality hazards to prevent Cartesian multiplicity explosions.
####################################################################################################

"""
=============================================================================
ENTERPRISE CARDINALITY & BRIDGE TABLE DETECTOR
=============================================================================
Defeats Weakness #5: Many-to-Many (M:N) Relationship Traps.
Inspects key multiplicity between two tables before joining:
1. One-to-One (1:1): Safe standard dimensional join.
2. One-to-Many (1:N): Standard Fact-to-Dimension join OR requires aggregation.
3. Many-to-Many (N:M): Critical danger zone! Identifies bridge table necessity
   to prevent catastrophic Cartesian row duplication.
=============================================================================
"""

import sys
from typing import Dict, Any, Optional
from pathlib import Path
import pandas as pd

if sys.platform == "win32":
    sys.stdout.reconfigure(encoding='utf-8')

def check_full_file_uniqueness(file_path: Optional[str], key_col: str) -> Optional[bool]:
    """Uses DuckDB to evaluate exact uniqueness across the entire file in milliseconds without RAM overhead."""
    if not file_path:
        return None
    try:
        import duckdb
        p = Path(file_path)
        if not p.exists() or p.suffix.lower() not in ['.csv', '.parquet']:
            return None
            
        con = duckdb.connect(':memory:')
        file_posix = p.as_posix().replace("'", "''")
        clean_col = key_col.replace('"', '""')
        if p.suffix.lower() == '.csv':
            sql = f"SELECT count(*), count(DISTINCT \"{clean_col}\") FROM read_csv_auto('{file_posix}', header=true, normalize_names=false, ignore_errors=true)"
        else:
            sql = f"SELECT count(*), count(DISTINCT \"{clean_col}\") FROM read_parquet('{file_posix}')"
        res = con.execute(sql).fetchone()
        con.close()
        if res and res[0] is not None and res[1] is not None:
            total_rows, distinct_keys = res[0], res[1]
            return (total_rows == distinct_keys) and (total_rows > 0)
    except Exception:
        return None
    return None

def detect_relationship_cardinality(
    df_left: pd.DataFrame, left_key: str,
    df_right: pd.DataFrame, right_key: str,
    left_file_path: Optional[str] = None,
    right_file_path: Optional[str] = None
) -> Dict[str, Any]:
    """
    Computes exact multiplicity and cardinality type between two candidate join keys.
    Utilizes DuckDB full-file scanning when available to eliminate sampling bias.
    """
    s_left = df_left[left_key].dropna()
    s_right = df_right[right_key].dropna()
    
    left_total = len(s_left)
    left_unique = s_left.nunique()
    left_is_unique = (left_total == left_unique) and (left_total > 0)
    
    right_total = len(s_right)
    right_unique = s_right.nunique()
    right_is_unique = (right_total == right_unique) and (right_total > 0)
    
    # Check full file out-of-core if path is supplied (defeats 2000-row sampling bias)
    if left_file_path:
        exact_left = check_full_file_uniqueness(left_file_path, left_key)
        if exact_left is not None:
            left_is_unique = exact_left
            
    if right_file_path:
        exact_right = check_full_file_uniqueness(right_file_path, right_key)
        if exact_right is not None:
            right_is_unique = exact_right
    
    # Check key overlap intersection
    shared_keys = set(s_left.unique()).intersection(set(s_right.unique()))
    overlap_count = len(shared_keys)
    
    if left_is_unique and right_is_unique:
        card_type = "1:1 (ONE-TO-ONE)"
        recommendation = "Safe direct relational merge. Referential integrity preserved."
        danger_level = "LOW"
    elif left_is_unique and not right_is_unique:
        card_type = "1:N (ONE-TO-MANY)"
        recommendation = "Right table has duplicate keys. If joining Right into Left, Right MUST be aggregated 1:1 first to prevent duplicate rows."
        danger_level = "MEDIUM"
    elif not left_is_unique and right_is_unique:
        card_type = "N:1 (MANY-TO-ONE)"
        recommendation = "Standard Fact-to-Dimension lookup join. Left table rows will be cleanly preserved without multiplication."
        danger_level = "LOW"
    else:
        card_type = "N:M (MANY-TO-MANY)"
        recommendation = "CRITICAL HAZARD: Both tables have duplicate keys. Direct join causes exponential Cartesian product (N x M rows). Star Schema requires a Bridge Table or Array Aggregation."
        danger_level = "HIGH"
        
    return {
        "left_key": left_key,
        "right_key": right_key,
        "cardinality": card_type,
        "danger_level": danger_level,
        "shared_keys_count": overlap_count,
        "left_unique_ratio": round(left_unique / max(left_total, 1), 4),
        "right_unique_ratio": round(right_unique / max(right_total, 1), 4),
        "architecture_recommendation": recommendation
    }

