def unpack_multisheet_excel_workbooks(folder: Path) -> set:
    """
    If an .xlsx / .xls workbook contains 2 or more valid data sheets (e.g., Orders,
    Shiprocket_RTO, Meta_Ads in a single file), unpacks each sheet into its own CSV
    `<workbook_stem>__<sheet_name>.csv` (applying per-sheet optimal header detection
    and summary row stripping) and returns the set of unpacked container .xlsx Paths.
    """
    unpacked_containers = set()
    skip_sheet_words = (
        'readme', 'cover', 'instruction', 'dictionary', 'metadata', 'notes',
        'summary_only', 'exec_summary', 'executive_summary', 'pivot', 'dashboard', 'overview', 'kpi', 'totals', 'rollup', 'chart'
    )
    for f in list(folder.iterdir()):
        if f.suffix.lower() not in ('.xlsx', '.xls') or f.name.startswith('~'):
            continue
        try:
            xl = pd.ExcelFile(f)
            if len(xl.sheet_names) < 2:
                continue
            valid_sheets = []
            for sname in xl.sheet_names:
                if any(w in sname.lower() for w in skip_sheet_words):
                    continue
                h_idx = detect_optimal_header_row(f, sheet_name=sname)
                df_tab = pd.read_excel(f, sheet_name=sname, header=h_idx)
                df_tab.columns = [str(c).strip() for c in df_tab.columns]
                df_tab = strip_accounting_summary_rows(df_tab)
                # Drop completely empty rows/columns
                df_tab = df_tab.dropna(how='all').dropna(axis=1, how='all')
                if len(df_tab) >= 2 and len(df_tab.columns) >= 2:
                    valid_sheets.append((sname, df_tab))
            if len(valid_sheets) >= 2:
                for sname, df_tab in valid_sheets:
                    clean_s = re.sub(r'[^A-Za-z0-9_]+', '_', sname.strip()).strip('_')
                    out_csv = folder / f"{f.stem}__{clean_s}.csv"
                    df_tab.to_csv(out_csv, index=False, encoding='utf-8')
                unpacked_containers.add(f.resolve())
                print(f"    [+] Auto-unpacked multi-tab Excel workbook '{f.name}' into {len(valid_sheets)} relational sheets.")
        except Exception as e:
            print(f"    [!] Warning inspecting multi-tab Excel '{f.name}': {e}")
    return unpacked_containers


def _has_strong_value_overlap(s1: pd.Series, s2: pd.Series, min_overlap: float = 0.50) -> bool:
    """
    Detects physical join-key relationship when column names differ completely
    (e.g., `order_id` vs `client_ref_no` or `acquisition_channel` vs `utm_source`)
    by measuring normalized value containment / Jaccard overlap >= 50%.
    Strictly rejects boolean {0,1,YES,NO} and small-integer measure columns.
    """
    if s1 is None or s2 is None:
        return False
    bool_tokens = {'0', '1', '0.0', '1.0', 'TRUE', 'FALSE', 'YES', 'NO', 'Y', 'N', 'NAN', 'NONE', 'NULL', ''}
    vals1 = {str(x).strip().upper() for x in s1.dropna().unique()[:500] if str(x).strip()} - bool_tokens
    vals2 = {str(x).strip().upper() for x in s2.dropna().unique()[:500] if str(x).strip()} - bool_tokens
    if len(vals1) < 2 or len(vals2) < 2:
        return False
    shared = vals1 & vals2
    if len(shared) < 2:
        return False
    # Reject plain small numbers (< 4 digits) so quantities/days/ratings never false-match
    all_plain_num = all(bool(re.match(r'^-?\d+(?:\.\d+)?$', v)) for v in shared)
    if all_plain_num:
        min_digits = min(len(v.split('.')[0].lstrip('-')) for v in shared)
        if min_digits < 4 or len(shared) < 10:
            return False
    denom = float(min(len(vals1), len(vals2)))
    return (len(shared) / denom) >= min_overlap

def get_best_excel_sheet(filepath: Path) -> Tuple[str, int]:
    """
    Scans all sheets in an Excel workbook and returns the sheet with the most rows.
    Avoids loading tiny 'Cover' or 'Readme' sheets.
    """
    try:
        import openpyxl
        wb = openpyxl.load_workbook(filepath, read_only=True)
        skip_words = ('readme', 'cover', 'instruction', 'dictionary', 'metadata', 'notes', 'summary_only')
        best_sheet = wb.sheetnames[0]
        max_rows = -1
        best_score = -1
        for name in wb.sheetnames:
            sheet = wb[name]
            r_count = int(sheet.max_row or 0)
            c_count = int(sheet.max_column or 0)
            is_cover = any(w in name.lower() for w in skip_words)
            score = (r_count * max(c_count, 1)) if not is_cover else -1
            if score > best_score:
                best_score = score
                max_rows = r_count
                best_sheet = name
        if best_score <= 0:
            for name in wb.sheetnames:
                r_count = int(wb[name].max_row or 0)
                if r_count > max_rows:
                    max_rows = r_count
                    best_sheet = name
        wb.close()
        return best_sheet, max(max_rows - 1, 0)
    except Exception:
        xl = pd.ExcelFile(filepath)
        return xl.sheet_names[0], 100

def inspect_file(filepath: Path) -> Tuple[Dict[str, Any], pd.DataFrame]:
    """Reads a representative sample and extracts schema and candidate keys."""
    ext = filepath.suffix.lower()
    t_name = filepath.stem
    selected_sheet = None
    
    detected_delim = None
    detected_enc = None
    
    if ext in ['.xlsx', '.xls']:
        sheet_name, total_rows = get_best_excel_sheet(filepath)
        selected_sheet = sheet_name
        header_row = detect_optimal_header_row(filepath, sheet_name=sheet_name)
        df_sample = pd.read_excel(filepath, sheet_name=sheet_name, header=header_row, nrows=SAMPLE_ROWS)
        total_rows = max(0, total_rows - header_row)
        if len(df_sample) < SAMPLE_ROWS:
            total_rows = len(df_sample)
    elif ext in ['.csv', '.tsv', '.txt']:
        header_row = detect_optimal_header_row(filepath)
        df_sample = smart_read_csv(filepath, header=header_row, nrows=SAMPLE_ROWS)
        enc, delim = detect_encoding_and_delimiter(filepath)
        detected_enc = enc
        detected_delim = delim
        with open(filepath, 'r', encoding=enc, errors='ignore') as f:
            raw_lines = sum(1 for _ in f)
        total_rows = max(0, raw_lines - 1 - header_row)
    elif ext == '.parquet':
        import pyarrow.parquet as pq
        table = pq.read_table(filepath)
        total_rows = table.num_rows
        df_sample = table.slice(0, SAMPLE_ROWS).to_pandas()
    elif ext == '.pdf':
        try:
            try:
                from .tally_pdf_ingestion import extract_table_from_pdf
            except (ImportError, ModuleNotFoundError):
                try:
                    try:
                        from tally_pdf_ingestion import extract_table_from_pdf
                    except (ImportError, ModuleNotFoundError):
                        pass
                except (ImportError, ModuleNotFoundError):
                    pass
        except ImportError:
            try:
                from tally_pdf_ingestion import extract_table_from_pdf
            except (ImportError, ModuleNotFoundError):
                pass
        df_full_pdf = extract_table_from_pdf(filepath)
        total_rows = len(df_full_pdf)
        df_sample = df_full_pdf.head(SAMPLE_ROWS)
    else:
        return None, None

    # Clean whitespace in column names
    df_sample.columns = [str(c).strip() for c in df_sample.columns]
    # Flatten hierarchical Tally/Marg grouped ledgers & strip mid-sheet subtotals
    try:
        try:
            try:
                from .tally_pdf_ingestion import flatten_grouped_accounting_ledger
            except (ImportError, ModuleNotFoundError):
                try:
                    try:
                        from tally_pdf_ingestion import flatten_grouped_accounting_ledger
                    except (ImportError, ModuleNotFoundError):
                        pass
                except (ImportError, ModuleNotFoundError):
                    pass
        except ImportError:
            try:
                from tally_pdf_ingestion import flatten_grouped_accounting_ledger
            except (ImportError, ModuleNotFoundError):
                pass
        pre_flat_len = len(df_sample)
        df_sample, _flat_meta = flatten_grouped_accounting_ledger(df_sample)
        dropped_flat = pre_flat_len - len(df_sample)
        if dropped_flat > 0:
            total_rows = max(0, total_rows - dropped_flat)
    except Exception:
        pass
    # Strip summary footer rows (e.g. Tally / Grand Total rows) and reconcile total row count
    cleaned_sample = strip_accounting_summary_rows(df_sample)
    dropped_summary_count = len(df_sample) - len(cleaned_sample)
    if dropped_summary_count > 0:
        total_rows = max(0, total_rows - dropped_summary_count)
        df_sample = cleaned_sample

    columns_meta = []
    potential_keys = []
    n_sample = len(df_sample)

    for col in df_sample.columns:
        s = df_sample[col].dropna()
        dtype = str(df_sample[col].dtype)
        nunique = int(s.nunique())
        samples = [str(x) for x in s.unique()[:3]]
        
        BAD_KEY_KEYWORDS = ['link', 'url', 'poster', 'image', 'photo', 'overview', 'description', 'desc', 'summary', 'text', 'comment', 'review', 'svg', 'png', 'jpg', 'jpeg', 'body', 'content', 'path', 'href']
        col_lower = str(col).lower()
        has_bad_keyword = any(b in col_lower for b in BAD_KEY_KEYWORDS)
        is_url_or_long_text = any(str(x).startswith(('http://', 'https://', '//', 'www.')) or len(str(x)) > 60 for x in samples)
        is_idx = is_index_artifact(col)
        
        has_key_keyword = any(k in col_lower for k in KEY_SEMANTIC_KEYWORDS) and not has_bad_keyword and not is_idx
        high_uniqueness = (n_sample > 10 and (nunique / float(n_sample)) >= 0.70) and not has_bad_keyword and not is_url_or_long_text and not is_idx
        
        if has_key_keyword or high_uniqueness:
            potential_keys.append(col)
            
        columns_meta.append({
            "name": col,
            "dtype": dtype,
            "sample_values": samples,
            "nunique_in_sample": nunique,
            "is_index_artifact": is_idx
        })
        
    strictly_unique_primary_keys = []
    if potential_keys:
        con = None
        try:
            import duckdb
            con = duckdb.connect()
            f_esc = str(filepath.resolve()).replace("'", "''")
            if ext in ['.csv', '.tsv', '.txt']:
                reader_sql = f"read_csv_auto('{f_esc}', ignore_errors=true)"
            elif ext == '.parquet':
                reader_sql = f"read_parquet('{f_esc}')"
            else:
                reader_sql = None
                
            if reader_sql:
                for pk_cand in potential_keys[:10]:
                    cand_esc = pk_cand.replace('"', '""')
                    row_stat = con.execute(f"SELECT COUNT(*), COUNT(DISTINCT \"{cand_esc}\") FROM {reader_sql}").fetchone()
                    if row_stat and row_stat[0] > 0 and row_stat[0] == row_stat[1]:
                        strictly_unique_primary_keys.append(pk_cand)
        except Exception:
            pass
        finally:
            if con is not None:
                try:
                    con.close()
                except Exception:
                    pass

    recommended_pk = "fact_surrogate_id"
    if strictly_unique_primary_keys:
        non_idx_keys = [c for c in strictly_unique_primary_keys if not is_index_artifact(c)]
        true_ids = [c for c in non_idx_keys if c.lower() in ['id', 'ident', 'uuid', 'key'] or c.lower().endswith(('_id', '_key', '_uuid'))]
        code_ids = [c for c in non_idx_keys if c.lower().endswith(('_code', '_num', '_no'))]
        clean_keys = [c for c in non_idx_keys if not any(b in c.lower() for b in BAD_KEY_KEYWORDS)]
        if true_ids:
            recommended_pk = true_ids[0]
        elif code_ids:
            recommended_pk = code_ids[0]
        elif clean_keys:
            recommended_pk = clean_keys[0]

    meta = {
        "table_name": t_name,
        "filename": filepath.name,
        "filepath": str(filepath.resolve()),
        "selected_sheet": selected_sheet,
        "estimated_rows": total_rows,
        "column_count": len(df_sample.columns),
        "potential_keys": potential_keys,
        "strictly_unique_primary_keys": strictly_unique_primary_keys,
        "recommended_primary_key": recommended_pk,
        "delimiter": detected_delim,
        "encoding": detected_enc,
        "columns": columns_meta
    }
    return meta, df_sample

def profile_raw_directory(dir_path: str, output_json: str = None) -> dict:
    folder = Path(dir_path)
    unpacked_xlsx = unpack_multisheet_excel_workbooks(folder)
    DOC_KEYWORDS = ['dictionary', 'datadictionary', 'codebook', 'metadata', 'data_description', 'field_description', 'description', 'readme', 'sample_submission', 'sample_sub']
    all_files = [
        f for f in folder.iterdir() 
        if f.suffix.lower() in ['.xlsx', '.xls', '.csv', '.parquet', '.tsv', '.txt', '.pdf'] 
        and f.resolve() not in unpacked_xlsx
        and not f.name.startswith('~')
        and not any(k in f.stem.lower() for k in DOC_KEYWORDS)
    ]
    
    # Self-Learning Defense: If 'train' partition split exists, ignore holdout 'test' split to prevent false relational dimension joins
    stems = [f.stem.lower() for f in all_files]
    if any(s == 'train' or s.startswith('train_') for s in stems):
        files = [f for f in all_files if not (f.stem.lower() == 'test' or f.stem.lower().startswith('test_'))]
    else:
        files = all_files
    
    print(f"[*] [Stage 1 Topology Profiler] Scanning {len(files)} files in {dir_path}...")
    tables = {}
    samples = {}
    
    for f in sorted(files):
        print(f"    - Profiling {f.name}...")
        meta, df_s = inspect_file(f)
        if meta:
            tables[meta["table_name"]] = meta
            samples[meta["table_name"]] = df_s
            
    # Generic Relational, Cardinality & Composite Key Analysis
    relational_hints = []
    cardinality_hazards = []
    composite_key_relations = []
    
    table_names = list(tables.keys())
    for i in range(len(table_names)):
        for j in range(i + 1, len(table_names)):
            t1_name = table_names[i]
            t2_name = table_names[j]
            t1 = tables[t1_name]
            t2 = tables[t2_name]
            df1 = samples[t1_name]
            df2 = samples[t2_name]
            
            # 1. Single Key Relationships & Cardinality Analysis
            for k1 in t1["potential_keys"]:
                for k2 in t2["potential_keys"]:
                    k1_l = k1.lower()
                    k2_l = k2.lower()
                    
                    is_candidate_match = (
                        k1_l == k2_l or
                        k1_l.endswith(f"_{k2_l}") or k2_l.endswith(f"_{k1_l}") or
                        (k1_l in k2_l and len(k1_l) >= 4) or (k2_l in k1_l and len(k2_l) >= 4) or
                        (('airport' in k1_l or 'ident' in k1_l or 'iata' in k1_l) and 
                         ('airport' in k2_l or 'ident' in k2_l or 'iata' in k2_l)) or
                        _has_strong_value_overlap(df1[k1], df2[k2], min_overlap=0.50)
                    )
                    
                    if is_candidate_match:
                        # Dynamically test key multiplicity (uses DuckDB full-file scan if available)
                        card_info = detect_relationship_cardinality(
                            df1, k1, df2, k2,
                            left_file_path=t1.get("filepath"),
                            right_file_path=t2.get("filepath")
                        )
                        
                        hint = {
                            "source_table": t1["table_name"],
                            "source_key": k1,
                            "target_table": t2["table_name"],
                            "target_key": k2,
                            "cardinality": card_info["cardinality"],
                            "danger_level": card_info["danger_level"],
                            "shared_keys_count": card_info["shared_keys_count"]
                        }
                        relational_hints.append(hint)
                        
                        # Automated Cardinality Hazards
                        if card_info["cardinality"].startswith("1:N"):
                            cardinality_hazards.append({
                                "table_pair": [t1["table_name"], t2["table_name"]],
                                "hazard": f"1-TO-MANY MULTIPLICITY HAZARD ({t1['table_name']}.{k1} -> {t2['table_name']}.{k2})",
                                "rule": f"Table '{t2['table_name']}' has duplicate keys for '{k2}'. Merging into '{t1['table_name']}' will duplicate fact rows.",
                                "defense_action": f"Table '{t2['table_name']}' MUST be pre-aggregated 1:1 on '{k2}' before join."
                            })
                        elif card_info["cardinality"].startswith("N:1"):
                            cardinality_hazards.append({
                                "table_pair": [t2["table_name"], t1["table_name"]],
                                "hazard": f"1-TO-MANY MULTIPLICITY HAZARD ({t2['table_name']}.{k2} -> {t1['table_name']}.{k1})",
                                "rule": f"Table '{t1['table_name']}' has duplicate keys for '{k1}'. Merging into '{t2['table_name']}' will duplicate fact rows.",
                                "defense_action": f"Table '{t1['table_name']}' MUST be pre-aggregated 1:1 on '{k1}' before join."
                            })
                        elif card_info["cardinality"].startswith("N:M"):
                            cardinality_hazards.append({
                                "table_pair": [t1["table_name"], t2["table_name"]],
                                "hazard": f"CRITICAL MANY-TO-MANY HAZARD ({t1['table_name']}.{k1} <-> {t2['table_name']}.{k2})",
                                "rule": f"Both '{t1['table_name']}' and '{t2['table_name']}' contain duplicate keys.",
                                "defense_action": f"Requires a dedicated bridge table or pre-aggregation to prevent exponential row explosion."
                            })

            # 2. Multi-Column Composite Key Detection
            comp_matches = detect_composite_join_mapping(df1, t1_name, df2, t2_name)
            if comp_matches:
                composite_key_relations.extend(comp_matches)

    # 3. Detect Multi-Reference Keys within the same table (e.g. Origin & Destination)
    TEMPORAL_WORDS = {'date', 'time', 'year', 'month', 'day', 'hour', 'minute', 'second', 'timestamp'}
    for t_name, t_meta in tables.items():
        keys = t_meta["potential_keys"]
        # Exclude temporal/timestamp columns from foreign key role pairing
        non_temporal_keys = [k for k in keys if not any(tw in k.lower() for tw in TEMPORAL_WORDS)]
        from_keys = [k for k in non_temporal_keys if any(x in k.lower() for x in ['from', 'origin', 'src', 'source'])]
        to_keys = [k for k in non_temporal_keys if any(x in k.lower() for x in ['to', 'dest', 'dst', 'target'])]
        if from_keys and to_keys:
            cardinality_hazards.append({
                "table_pair": [t_name, "Dimension_Lookup"],
                "hazard": f"DUAL/MULTI FOREIGN KEY REFERENCE IN '{t_name}'",
                "rule": f"Table '{t_name}' references dimensions with paired roles ({from_keys[0]} & {to_keys[0]}).",
                "defense_action": f"Requires dual joins with role prefixes (e.g. 'from_' and 'to_')."
            })

    raw_profile = {
        "dataset_name": folder.name,
        "tables": {k: {
            "table_name": v.get("table_name", k),
            "filename": v.get("filename", f"{k}.csv"),
            "selected_sheet": v.get("selected_sheet"),
            "estimated_rows": v["estimated_rows"],
            "delimiter": v.get("delimiter"),
            "encoding": v.get("encoding"),
            "columns": [c["name"] for c in v["columns"]],
            "potential_keys": v["potential_keys"],
            "strictly_unique_primary_keys": v.get("strictly_unique_primary_keys", []),
            "recommended_primary_key": v.get("recommended_primary_key", "fact_surrogate_id"),
            "sample_columns": v["columns"][:12]
        } for k, v in tables.items()},
        "relational_hints": relational_hints,
        "cardinality_hazards": cardinality_hazards,
        "composite_key_relations": composite_key_relations
    }
    
    # 100% Local PII Scrubbing before export/transmission
    sanitized_profile = scrub_schema_payload(raw_profile)
    
    if output_json:
        safe_dump_json(sanitized_profile, output_json, indent=2)
        print(f"[+] [Stage 1 Topology Profiler] Sanitized Schema Topology saved to: {output_json}")
        
    return sanitized_profile

if False and __name__ == "__main__":  # Section CLI preserved for reference
    target_dir = sys.argv[1] if len(sys.argv) > 1 else "raw_data"
    out_file = sys.argv[2] if len(sys.argv) > 2 else "autonomous_engine/schema_topology.json"
    p = profile_raw_directory(target_dir, out_file)
    print("\n--- SCHEMA SUMMARY ---")
    for t, m in p["tables"].items():
        print(f"Table: {t:<15} | Sheet: {str(m.get('selected_sheet')):<12} | Rows: ~{m['estimated_rows']:<8} | Cols: {len(m['columns'])}")
    print("\n--- HAZARDS DETECTED ---")
    for h in p["cardinality_hazards"]:
        print(f"[*] {h['hazard']}: {h['defense_action']}")


####################################################################################################
# SECTION 17 // AGENT 2.1: MULTI-KEY API POOL & RATE LIMITER MANAGER
# STAGE      : Stage 2 - Blueprint Formulation
# SOURCE FILE: autonomous_engine/rate_limiter.py
# DESCRIPTION: Manages multi-key API rate-limiting pool across Gemini endpoints (28 RPM safety guard).
####################################################################################################

"""
=============================================================================
ENTERPRISE MULTI-KEY RATE LIMITER & LOAD BALANCER FOR GEMINI API
=============================================================================
Architecture:
1. Multi-Key Pooling: Automatically aggregates GEMINI_API_KEY and
   GEMINI_API_KEY_SECONDARY (and any GEMINI_API_KEY_N in .env).
2. Throughput Multiplier: Safe quota scales linearly:
   1 Key = 14 RPM | 2 Keys = 28 RPM | 3 Keys = 42 RPM.
3. Zero-Wait Key Balancing: If Key 1 reaches 14 calls in the last 60s,
   automatically routes the request to Key 2 with 0 seconds wait time.
4. Instant Failover: On HTTP 429 (Resource Exhausted) or 503, immediately
   switches to the next available healthy key.
5. Cross-Process State: Uses SQLite ledger (`runs/api_rate_limit.db`) to ensure
   Streamlit and CLI share quotas seamlessly.
=============================================================================
"""

import os
import sys
import time
import random
import sqlite3
import threading
from collections import deque
from pathlib import Path
from dotenv import load_dotenv
from google import genai

if sys.platform == "win32" and hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding='utf-8')

_ENGINE_DIR = Path(__file__).resolve().parent
_WORKSPACE_ROOT = _ENGINE_DIR.parent if _ENGINE_DIR.name == "autonomous_engine" else _ENGINE_DIR
load_dotenv(_WORKSPACE_ROOT / ".env")
load_dotenv()

_LOGGED_POOL_BANNER = False
_DEAD_GEMINI_MODELS = set()

# Official Google Gemini API 2026 per-1M-token USD pricing table (Input / Output incl. thinking)
_MODEL_PRICING_PER_1M_USD = {
    "gemini-3.5-flash-lite": (0.30, 2.50),
    "gemini-3.5-flash": (0.30, 2.50),
    "gemini-3.8-flash": (0.75, 3.75),
    "gemini-2.5-flash": (0.30, 2.50),
    "gemini-2.5-pro": (1.25, 10.00),
}
_DEFAULT_MODEL_PRICING_USD = (0.30, 2.50)
_USD_TO_INR_RATE = 85.0
_USAGE_LOCK = threading.Lock()
_GLOBAL_TOKEN_LEDGER = {
    "calls": [],
    "total_calls": 0,
    "prompt_tokens": 0,
    "output_tokens": 0,
    "thoughts_tokens": 0,
    "total_tokens": 0,
    "total_cost_usd": 0.0,
    "total_cost_inr": 0.0,
}


def reset_token_usage_ledger() -> None:
    with _USAGE_LOCK:
        _GLOBAL_TOKEN_LEDGER["calls"].clear()
        _GLOBAL_TOKEN_LEDGER["total_calls"] = 0
        _GLOBAL_TOKEN_LEDGER["prompt_tokens"] = 0
        _GLOBAL_TOKEN_LEDGER["output_tokens"] = 0
        _GLOBAL_TOKEN_LEDGER["thoughts_tokens"] = 0
        _GLOBAL_TOKEN_LEDGER["total_tokens"] = 0
        _GLOBAL_TOKEN_LEDGER["total_cost_usd"] = 0.0
        _GLOBAL_TOKEN_LEDGER["total_cost_inr"] = 0.0


def get_token_usage_summary() -> dict:
    with _USAGE_LOCK:
        return {
            "total_calls": _GLOBAL_TOKEN_LEDGER["total_calls"],
            "prompt_tokens": _GLOBAL_TOKEN_LEDGER["prompt_tokens"],
            "output_tokens": _GLOBAL_TOKEN_LEDGER["output_tokens"],
            "thoughts_tokens": _GLOBAL_TOKEN_LEDGER["thoughts_tokens"],
            "total_tokens": _GLOBAL_TOKEN_LEDGER["total_tokens"],
            "total_cost_usd": round(_GLOBAL_TOKEN_LEDGER["total_cost_usd"], 6),
            "total_cost_inr": round(_GLOBAL_TOKEN_LEDGER["total_cost_inr"], 4),
            "calls": list(_GLOBAL_TOKEN_LEDGER["calls"]),
        }


def _record_usage_metadata(model: str, resp, latency_sec: float) -> None:
    um = getattr(resp, "usage_metadata", None)
    p_tok = int(getattr(um, "prompt_token_count", 0) or 0) if um else 0
    c_tok = int(getattr(um, "candidates_token_count", 0) or 0) if um else 0
    t_tok = int(getattr(um, "thoughts_token_count", 0) or 0) if um else 0
    tot_tok = int(getattr(um, "total_token_count", 0) or (p_tok + c_tok + t_tok)) if um else 0
    in_rate, out_rate = _MODEL_PRICING_PER_1M_USD.get(model, _DEFAULT_MODEL_PRICING_USD)
    cost_usd = (p_tok / 1_000_000.0) * in_rate + ((c_tok + t_tok) / 1_000_000.0) * out_rate
    cost_inr = cost_usd * _USD_TO_INR_RATE
    with _USAGE_LOCK:
        _GLOBAL_TOKEN_LEDGER["total_calls"] += 1
        _GLOBAL_TOKEN_LEDGER["prompt_tokens"] += p_tok
        _GLOBAL_TOKEN_LEDGER["output_tokens"] += c_tok
        _GLOBAL_TOKEN_LEDGER["thoughts_tokens"] += t_tok
        _GLOBAL_TOKEN_LEDGER["total_tokens"] += tot_tok
        _GLOBAL_TOKEN_LEDGER["total_cost_usd"] += cost_usd
        _GLOBAL_TOKEN_LEDGER["total_cost_inr"] += cost_inr
        _GLOBAL_TOKEN_LEDGER["calls"].append({
            "model": model,
            "prompt_tokens": p_tok,
            "output_tokens": c_tok,
            "thoughts_tokens": t_tok,
            "total_tokens": tot_tok,
            "latency_sec": round(latency_sec, 2),
            "cost_usd": round(cost_usd, 6),
            "cost_inr": round(cost_inr, 4),
        })


def _resolve_default_rpm(explicit_rpm=None) -> int:
    """
    Resolves per-key RPM limit cleanly:
      - Uses explicit_rpm when caller specifies a positive integer.
      - Otherwise reads GEMINI_MAX_RPM from environment (default: 14 for Free Tier keys).
    """
    if explicit_rpm is not None:
        return max(1, int(explicit_rpm))
    raw_env = str(os.getenv("GEMINI_MAX_RPM", "") or "").strip()
    if raw_env:
        try:
            parsed = int(raw_env)
            if parsed >= 1:
                return parsed
        except ValueError:
            pass
    return 14


class PacedGeminiClient:
    def __init__(self, api_key: str = None, max_calls_per_minute: int = None, model: str = "gemini-3.5-flash-lite", quiet: bool = False):
        # 1. Discover all configured API keys
        keys = []
        if api_key:
            keys.append(api_key.strip())
        else:
            primary = os.getenv("GEMINI_API_KEY")
            secondary = os.getenv("GEMINI_API_KEY_SECONDARY")
            if primary:
                keys.append(primary.strip())
            if secondary and secondary.strip() not in keys:
                keys.append(secondary.strip())
            # Scan for any additional GEMINI_API_KEY_3, etc.
            for k, v in os.environ.items():
                if k.startswith("GEMINI_API_KEY_") and k != "GEMINI_API_KEY_SECONDARY":
                    if v and v.strip() not in keys:
                        keys.append(v.strip())

        if not keys:
            raise ValueError("No Gemini API keys found! Please configure GEMINI_API_KEY in .env.")

        self.api_keys = keys
        self.num_keys = len(keys)
        
        from google.genai import types
        # Initialize an independent API client for each key
        self.clients = [
            genai.Client(api_key=k, http_options=types.HttpOptions(timeout=90000))
            for k in self.api_keys
        ]
        
        eff_rpm = _resolve_default_rpm(max_calls_per_minute)
        self.model = model
        self.max_calls_per_key = eff_rpm
        self.total_max_calls = eff_rpm * self.num_keys
        self.window_seconds = 60.0
        self.total_calls_made = 0
        self._lock = threading.Lock()
        self._thread_local = threading.local()
        try:
            self.max_queue_wait_seconds = max(5.0, float(os.getenv("GEMINI_MAX_QUEUE_WAIT_SEC", "90.0")))
        except ValueError:
            self.max_queue_wait_seconds = 90.0

        # Cross-process shared rate-limit ledger (anchored to workspace root)
        self.db_dir = (_WORKSPACE_ROOT / "runs").resolve()
        self.db_dir.mkdir(parents=True, exist_ok=True)
        self.db_path = self.db_dir / "api_rate_limit.db"
        self._init_shared_db()
        
        global _LOGGED_POOL_BANNER
        if not quiet and not _LOGGED_POOL_BANNER:
            print(f"[*] [Rate Limiter] Initialized Multi-Key Pool with {self.num_keys} Key(s) (Total Capacity: {self.total_max_calls} RPM, Model: {self.model})")
            _LOGGED_POOL_BANNER = True

    @property
    def _override_models(self):
        """Thread-local model override list so concurrent FastAPI requests never bleed tiers."""
        if not hasattr(self._thread_local, "override_models"):
            raise AttributeError("_override_models")
        return self._thread_local.override_models

    @_override_models.setter
    def _override_models(self, models) -> None:
        self._thread_local.override_models = list(models) if models is not None else None

    @_override_models.deleter
    def _override_models(self) -> None:
        if hasattr(self._thread_local, "override_models"):
            delattr(self._thread_local, "override_models")

    def _init_shared_db(self):
        try:
            conn = sqlite3.connect(self.db_path, timeout=15.0)
            cur = conn.cursor()
            cur.execute("PRAGMA journal_mode=WAL;")
            # Ensure schema has key_id column
            cur.execute("CREATE TABLE IF NOT EXISTS api_calls (key_id TEXT, call_time REAL);")
            cur.execute("PRAGMA table_info(api_calls);")
            cols = [c[1] for c in cur.fetchall()]
            if "key_id" not in cols:
                cur.execute("DROP TABLE IF EXISTS api_calls;")
                cur.execute("CREATE TABLE api_calls (key_id TEXT, call_time REAL);")
            conn.commit()
            conn.close()
        except Exception:
            pass

    def _wait_for_slot(self, preferred_key_idx: int = None) -> int:
        """
        Enforces sliding-window rate limit across all keys and processes.
        Returns the index of the key client with an immediately available slot,
        or raises TimeoutError if the bounded queue wait ceiling is exceeded.
        """
        deadline = time.monotonic() + float(getattr(self, "max_queue_wait_seconds", 90.0))
        while True:
            min_sleep_needed = float('inf')
            with self._lock:
                now = time.time()
                try:
                    conn = sqlite3.connect(self.db_path, timeout=10.0)
                    cur = conn.cursor()
                    # Evict entries older than 60s
                    cur.execute("DELETE FROM api_calls WHERE call_time <= ?;", (now - self.window_seconds,))
                    
                    # Order of key evaluation: preferred first if given, else round-robin
                    key_indices = list(range(self.num_keys))
                    if preferred_key_idx is not None and preferred_key_idx in key_indices:
                        key_indices.remove(preferred_key_idx)
                        key_indices.insert(0, preferred_key_idx)
                    
                    for idx in key_indices:
                        key_tag = f"key_{idx}"
                        cur.execute("SELECT count(*), min(call_time) FROM api_calls WHERE key_id = ?;", (key_tag,))
                        cnt, oldest = cur.fetchone()
                        cnt = cnt or 0
                        
                        if cnt < self.max_calls_per_key:
                            # Slot available on this key! Register and return immediately!
                            cur.execute("INSERT INTO api_calls (key_id, call_time) VALUES (?, ?);", (key_tag, now))
                            conn.commit()
                            conn.close()
                            self.total_calls_made += 1
                            return idx
                        else:
                            # Key is full; calculate when its next slot will free up
                            if oldest is not None:
                                key_sleep = (oldest + self.window_seconds) - now + 0.5
                                if key_sleep < min_sleep_needed:
                                    min_sleep_needed = key_sleep
                                    
                    conn.close()
                except Exception:
                    # Enforce conservative pacing sleep if SQLite ledger is transiently locked
                    fallback_sleep = max(self.window_seconds / max(self.total_max_calls, 1), 2.1)
                    time.sleep(fallback_sleep)
                    idx_fallback = self.total_calls_made % self.num_keys
                    self.total_calls_made += 1
                    return idx_fallback

            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise TimeoutError(
                    f"Gemini rate-limit queue wait exceeded {self.max_queue_wait_seconds:.1f}s "
                    f"({self.num_keys} key(s), {self.total_max_calls} RPM cap). "
                    "Set GEMINI_MAX_RPM for paid API keys or retry shortly."
                )

            # If all keys in the pool are at capacity, sleep until the earliest key clears a slot (bounded by deadline)
            sleep_for = min_sleep_needed if (min_sleep_needed < float('inf') and min_sleep_needed > 0) else 1.0
            sleep_for = min(sleep_for, max(0.1, remaining))
            if min_sleep_needed < float('inf') and min_sleep_needed > 0:
                print(f"\n[RATE-LIMIT PACER] All {self.num_keys} API keys at capacity ({self.total_max_calls} RPM).", flush=True)
                print(f"[RATE-LIMIT PACER] Sleeping {sleep_for:.1f}s for next available slot...", flush=True)
            time.sleep(sleep_for)

    def generate_content(self, contents, system_instruction: str = None, max_retries: int = 5) -> str:
        """
        Calls Gemini API with multi-key load balancing, auto-failover, and resilience.
        """
        last_error = None
        preferred_idx = self.total_calls_made % self.num_keys
        preferred_models = getattr(self, "_override_models", None) or [
            self.model,
            "gemini-2.5-flash",
            "gemini-3.5-flash-lite",
            "gemini-3.8-flash",
            "gemini-3.5-flash",
        ]
        candidate_models = [
            m for m in dict.fromkeys(preferred_models)
            if m not in _DEAD_GEMINI_MODELS
        ] or ["gemini-2.5-flash"]
        
        for attempt in range(1, max_retries + 1):
            client_idx = self._wait_for_slot(preferred_key_idx=preferred_idx)
            active_client = self.clients[client_idx]
            live_models = [m for m in candidate_models if m not in _DEAD_GEMINI_MODELS] or ["gemini-2.5-flash"]
            current_model = live_models[(attempt - 1) % len(live_models)]
            
            try:
                kwargs = {"model": current_model, "contents": contents}
                if system_instruction:
                    kwargs["config"] = {"system_instruction": system_instruction}
                
                t_call0 = time.time()
                resp = active_client.models.generate_content(**kwargs)
                _record_usage_metadata(current_model, resp, time.time() - t_call0)
                return resp.text.strip()
                
            except Exception as e:
                last_error = e
                err_str = str(e)
                is_not_found = "404" in err_str or "not_found" in err_str.lower()
                is_rate_limit = any(k in err_str.lower() for k in ["429", "quota", "resource_exhausted", "rate_limit"])
                is_server_error = any(k in err_str.lower() for k in ["503", "unavailable", "deadline", "504"])
                if is_not_found:
                    _DEAD_GEMINI_MODELS.add(current_model)
                    preferred_idx = (client_idx + 1) % self.num_keys
                    continue
                if is_server_error:
                    # Transient server blip (503/504): switch key, cycle model, and pause briefly
                    wait_time = min(1.0 * attempt, 2.5)
                    next_idx = (client_idx + 1) % self.num_keys
                    next_models = [m for m in candidate_models if m not in _DEAD_GEMINI_MODELS] or ["gemini-2.5-flash"]
                    next_model = next_models[attempt % len(next_models)]
                    print(f"\n[!] Server/Endpoint notice: {err_str[:60]}... (Attempt {attempt}/{max_retries}). Switching to Key #{next_idx + 1}, Model '{next_model}' and pausing {wait_time:.1f}s...", flush=True)
                    preferred_idx = next_idx
                    time.sleep(wait_time)
                    continue

                if is_rate_limit:
                    if self.num_keys > 1 and attempt <= self.num_keys:
                        next_idx = (client_idx + 1) % self.num_keys
                        print(f"\n[!] Quota 429 on Key #{client_idx + 1}. Instant failover to Key #{next_idx + 1}!", flush=True)
                        preferred_idx = next_idx
                        continue
                    wait_time = (2 ** attempt) * 4 + random.uniform(1.0, 3.0)
                    print(f"\n[!] Quota Warning across pool (Attempt {attempt}/{max_retries}). Backing off {wait_time:.1f}s...", flush=True)
                    time.sleep(wait_time)
                else:
                    wait_time = 2.0 * attempt
                    print(f"\n[!] Transient API notice: {e}. Retrying in {wait_time:.1f}s (Attempt {attempt}/{max_retries})...", flush=True)
                    time.sleep(wait_time)
                    
        # Multi-Provider Failover: Only route to free OpenRouter endpoints if explicitly permitted by privacy config
        allow_free_failover = (
            os.getenv("ALLOW_FREE_OPENROUTER_FAILOVER", "false").strip().lower() in ("1", "true", "yes")
            or os.getenv("LLM_PROVIDER", "gemini").strip().lower() in ("nemotron", "openrouter")
        )
        if allow_free_failover and os.getenv("OPENROUTER_API_KEY"):
            print("\n[!] Gemini Pool Exhausted! Explicit OpenRouter Failover Permitted — Routing...", flush=True)
            try:
                try:
                    try:
                        from .pii_scrubber import scrub_text
                    except (ImportError, ModuleNotFoundError):
                        try:
                            try:
                                from pii_scrubber import scrub_text
                            except (ImportError, ModuleNotFoundError):
                                pass
                        except (ImportError, ModuleNotFoundError):
                            pass
                except ImportError:
                    try:
                        try:
                            from pii_scrubber import scrub_text
                        except (ImportError, ModuleNotFoundError):
                            pass
                    except ImportError:
                        scrub_text = lambda s: s
                safe_contents = scrub_text(contents) if isinstance(contents, str) else contents
                return call_openrouter_model(safe_contents, system_instruction=system_instruction)
            except Exception as ore:
                print(f"[X] OpenRouter failover notice: {ore}", flush=True)

        raise RuntimeError(f"Failed to complete Gemini API call after {max_retries} attempts. Last error: {last_error}")

    def generate_content_tiered(self, contents, system_instruction: str = None, tier: str = "fast", max_retries: int = 5) -> str:
        """
        Cost-smart tiered routing:
          - tier='fast': uses low-cost Hydrogen/Flash models for routine tasks & Attempt 1 fixes.
          - tier='reasoning': escalates to Carbon/Pro deep-reasoning model when fast retries fail.
        """
        if str(tier).lower() == "reasoning":
            self._override_models = ["gemini-2.5-pro", "gemini-3.5-flash", "gemini-2.5-flash"]
        try:
            return self.generate_content(contents=contents, system_instruction=system_instruction, max_retries=max_retries)
        finally:
            if hasattr(self, "_override_models"):
                delattr(self, "_override_models")

    def generate_text(self, prompt: str = "", system_instruction: str = None, max_retries: int = 3, **kwargs) -> str:
        """Convenience alias used by Q&A and Bespoke Dashboard engines."""
        contents = prompt if prompt else kwargs.get("contents", "")
        return self.generate_content(contents=contents, system_instruction=system_instruction, max_retries=max_retries)

    def get_pool_status(self) -> dict:
        """Returns live health and capacity telemetry for the multi-key pool."""
        return {
            "num_keys": self.num_keys,
            "max_calls_per_key": self.max_calls_per_key,
            "total_max_calls_rpm": self.total_max_calls,
            "model": self.model,
            "total_calls_made": self.total_calls_made,
            "db_path": str(self.db_path),
        }

def call_openrouter_model(
    prompt: str,
    system_instruction: str = None,
    model: str = "nvidia/nemotron-3-ultra-550b-a55b:free",
    api_key: str = None
) -> str:
    """
    Direct call to OpenRouter API with multi-model fallback.
    """
    import urllib.request
    import json
    
    key = api_key or os.getenv("OPENROUTER_API_KEY")
    if not key:
        raise ValueError("OPENROUTER_API_KEY not configured in .env!")
    
    candidate_models = [
        model,
        "nvidia/nemotron-3-ultra-550b-a55b:free",
        "google/gemini-2.0-flash-exp:free",
        "meta-llama/llama-3.3-70b-instruct:free",
    ]
    seen = set()
    models_to_try = [m for m in candidate_models if not (m in seen or seen.add(m))]
    
    messages = []
    if system_instruction:
        messages.append({"role": "system", "content": system_instruction})
    messages.append({"role": "user", "content": prompt})

    last_err = None
    for cand in models_to_try:
        try:
            payload = json.dumps({
                "model": cand,
                "messages": messages,
                "temperature": 0.2
            }).encode("utf-8")

            req = urllib.request.Request(
                "https://openrouter.ai/api/v1/chat/completions",
                data=payload,
                headers={
                    "Authorization": f"Bearer {key}",
                    "Content-Type": "application/json",
                    "HTTP-Referer": "https://github.com/datax-ray/autonomous-engine",
                    "X-Title": "DataX-Ray Autonomous AI Engine"
                }
            )
            with urllib.request.urlopen(req, timeout=75) as resp:
                data = json.loads(resp.read().decode("utf-8"))
                if "choices" in data and len(data["choices"]) > 0:
                    msg = data["choices"][0].get("message", {})
                    content = msg.get("content", "").strip()
                    if content:
                        print(f"[+] [OpenRouter] Succeeded via model: {cand}", flush=True)
                        return content
                if "error" in data:
                    print(f"[!] OpenRouter candidate {cand} error: {data['error']}", flush=True)
                    last_err = data["error"]
        except Exception as e:
            print(f"[!] OpenRouter candidate {cand} exception: {e}", flush=True)
            last_err = e
            time.sleep(1.0)
            continue

    raise RuntimeError(f"All OpenRouter fallback models failed. Last error: {last_err}")

if False and __name__ == "__main__":  # Section CLI preserved for reference
    pacer = PacedGeminiClient()
    print(f"\n[*] Testing Multi-Key Pool with {pacer.num_keys} keys on model '{pacer.model}'...")
    res = pacer.generate_content("Say 'Multi-Key Load Balancer Operational!' in one short sentence.")
    print(f"[+] Output: {res}")



