    blueprint["dataset_fingerprint"] = current_fp
    safe_dump_json(blueprint, output_blueprint_path, indent=2)
    print(f"[+] [Stage 2 Blueprint] Relational Blueprint successfully saved to: {output_blueprint_path}")
