    o_dir = sys.argv[5] if len(sys.argv) > 5 else "output"
    c_dir = sys.argv[6] if len(sys.argv) > 6 else "cache"
    generate_dynamic_etl_script(bp_path, sc_path, top_path, data_dir=d_dir, output_dir=o_dir, cache_dir=c_dir)


